import{_ as t,c as a,o as s,ae as r}from"./chunks/framework.Cd-3tpCq.js";const p=JSON.parse('{"title":"Create Newsletter","description":"","frontmatter":{"outline":false,"examples":[{"id":"create-newsletter-basic","title":"Subscribe to Newsletter","description":"Subscribe an email address to the newsletter on the current channel. A customer token is optional and only links the subscription to that account.","query":"mutation createNewsletter($input: createNewsletterInput!) {\\n  createNewsletter(input: $input) {\\n    newsletter {\\n      success\\n      message\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"customerEmail\\": \\"jane@example.com\\"\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createNewsletter\\": {\\n      \\"newsletter\\": {\\n        \\"success\\": true,\\n        \\"message\\": \\"You have subscribed to the newsletter successfully.\\"\\n      }\\n    }\\n  }\\n}\\n","commonErrors":[{"error":"UNAUTHENTICATED","cause":"The storefront key header was missing or wrong","solution":"Login and provide a valid customer authentication token"},{"error":"invalid-email","cause":"The email address provided is not valid","solution":"Use a properly formatted email address"},{"error":"already-subscribed","cause":"The email already exists in the subscribers list","solution":"Use an email that is not already subscribed"}]},{"id":"create-newsletter-with-mutation-id","title":"Subscribe to Newsletter - With Client Mutation ID","description":"Subscribe and track the mutation with a client-side identifier.","query":"mutation createNewsletter($input: createNewsletterInput!) {\\n  createNewsletter(input: $input) {\\n    newsletter {\\n      success\\n      message\\n    }\\n    clientMutationId\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"customerEmail\\": \\"john.doe@example.com\\",\\n    \\"clientMutationId\\": \\"newsletter-001\\"\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createNewsletter\\": {\\n      \\"newsletter\\": {\\n        \\"success\\": true,\\n        \\"message\\": \\"You have subscribed to the newsletter successfully.\\"\\n      },\\n      \\"clientMutationId\\": \\"newsletter-001\\"\\n    }\\n  }\\n}\\n","commonErrors":[{"error":"UNAUTHENTICATED","cause":"The storefront key header was missing or wrong","solution":"Login and provide a valid customer authentication token"},{"error":"validation-error","cause":"The email field fails server-side validation","solution":"Provide a valid, non-empty, unique email address"}]}]},"headers":[],"relativePath":"api/graphql-api/shop/mutations/create-newsletter.md","filePath":"api/graphql-api/shop/mutations/create-newsletter.md"}'),n={name:"api/graphql-api/shop/mutations/create-newsletter.md"};function i(o,e,c,l,d,u){return s(),a("div",null,e[0]||(e[0]=[r('<h1 id="create-newsletter" tabindex="-1">Create Newsletter <a class="header-anchor" href="#create-newsletter" aria-label="Permalink to &quot;Create Newsletter&quot;">​</a></h1><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>The <code>createNewsletter</code> mutation subscribes an email address to the store newsletter on the current channel. Use this mutation to:</p><ul><li>Add newsletter opt-in to the storefront footer or account page</li><li>Re-subscribe a customer who previously unsubscribed</li><li>Capture marketing consent during registration or checkout</li><li>Track submissions using <code>clientMutationId</code></li></ul><p>The subscription is scoped to the current channel.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>The mutation is public — the storefront key alone is enough, so a footer signup form works for guests.</p><p>A customer token is optional. When one is sent, the subscription is linked to that customer&#39;s account; without it the row is stored as a guest subscription.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Authorization: Bearer &lt;accessToken&gt;</span></span></code></pre></div><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>input</code></td><td><code>createNewsletterInput!</code></td><td>✅ Yes</td><td>Input object containing the subscription fields.</td></tr></tbody></table><h3 id="input-fields-createnewsletterinput" tabindex="-1">Input Fields (<code>createNewsletterInput</code>) <a class="header-anchor" href="#input-fields-createnewsletterinput" aria-label="Permalink to &quot;Input Fields (`createNewsletterInput`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>customerEmail</code></td><td><code>String!</code></td><td>✅ Yes</td><td>Email address to subscribe. Must be valid and unique in the subscribers list.</td></tr><tr><td><code>clientMutationId</code></td><td><code>String</code></td><td>❌ No</td><td>Optional client-side identifier for tracking the mutation request.</td></tr></tbody></table><h2 id="possible-returns" tabindex="-1">Possible Returns <a class="header-anchor" href="#possible-returns" aria-label="Permalink to &quot;Possible Returns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>newsletter.success</code></td><td><code>Boolean!</code></td><td><code>true</code> if the subscription was created successfully.</td></tr><tr><td><code>newsletter.message</code></td><td><code>String!</code></td><td>Human-readable confirmation or error message.</td></tr><tr><td><code>clientMutationId</code></td><td><code>String</code></td><td>Echoed back from the input if provided.</td></tr></tbody></table><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><h3 id="_1-storefront-footer-opt-in" tabindex="-1">1. Storefront Footer Opt-in <a class="header-anchor" href="#_1-storefront-footer-opt-in" aria-label="Permalink to &quot;1. Storefront Footer Opt-in&quot;">​</a></h3><p>Trigger this mutation when a logged-in customer submits the newsletter form, then display <code>message</code> as feedback.</p><h3 id="_2-account-preferences" tabindex="-1">2. Account Preferences <a class="header-anchor" href="#_2-account-preferences" aria-label="Permalink to &quot;2. Account Preferences&quot;">​</a></h3><p>Let customers manage their marketing consent from the account settings page.</p><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ol><li><strong>Validate email client-side first</strong> to reduce unnecessary API calls.</li><li><strong>Always read <code>success</code></strong> before showing a success state.</li><li><strong>Handle the already-subscribed case</strong> gracefully — surface the server <code>message</code>.</li></ol><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/newsletter/subscribe.html">Subscribe to Newsletter (REST)</a></li><li><a href="/api/graphql-api/shop/mutations/customer-login.html">Customer Login</a></li><li><a href="/api/graphql-api/shop-api.html">Shop API Overview</a></li></ul>',24)]))}const b=t(n,[["render",i]]);export{p as __pageData,b as default};
